import re
import struct

_INFO = {
    "char": (1, "c"), "bool": (1, "?"), "int8_t": (1, "b"), "uint8_t": (1, "B"),
    "short": (2, "h"), "int16_t": (2, "h"), "uint16_t": (2, "H"),
    "int": (4, "i"), "int32_t": (4, "i"), "uint32_t": (4, "I"), "float": (4, "f"),
    "long long": (8, "q"), "int64_t": (8, "q"), "uint64_t": (8, "Q"), "double": (8, "d"), "pointer": (8, "Q"),
}


def _parse(c_type):
    m = re.fullmatch(r"\s*(.+?)\s*\[\s*(\d+)\s*\]\s*", c_type)
    base, count = (m.group(1), int(m.group(2))) if m else (c_type, None)
    base = " ".join(base.split())
    if base not in _INFO or (count is not None and count < 1):
        raise ValueError(f"bad type: {c_type!r}")
    return base, count


def _plan(fields, pack):
    items, end, struct_align = [], 0, 1
    for name, c_type in fields:
        base, count = _parse(c_type)
        size, code = _INFO[base]
        align = min(size, pack) if pack else size
        offset = (end + align - 1) // align * align
        items.append((name, base, count, offset - end, code))
        end = offset + size * (count or 1)
        struct_align = max(struct_align, align)
    total = (end + struct_align - 1) // struct_align * struct_align
    return items, total - end


def struct_format(fields, pack=None):
    items, tail = _plan(fields, pack)
    parts = ["<"]
    for _name, base, count, padding, code in items:
        if padding:
            parts.append(f"{padding}x")
        if count is None:
            parts.append(code)
        elif base == "char":
            parts.append(f"{count}s")
        else:
            parts.append(f"{count}{code}")
    if tail:
        parts.append(f"{tail}x")
    return "".join(parts)


def pack_record(fields, values, pack=None):
    items, _ = _plan(fields, pack)
    args = []
    for name, base, count, _padding, _code in items:
        value = values[name]
        if count is not None and base != "char":
            args.extend(value)
        else:
            args.append(value)
    return struct.pack(struct_format(fields, pack), *args)


def unpack_record(fields, data, pack=None):
    fmt = struct_format(fields, pack)
    if len(data) != struct.calcsize(fmt):
        raise ValueError("data has the wrong size for this structure")
    flat = list(struct.unpack(fmt, data))
    items, _ = _plan(fields, pack)
    result = {}
    for name, base, count, _padding, _code in items:
        if count is not None and base != "char":
            result[name], flat = flat[:count], flat[count:]
        else:
            result[name] = flat.pop(0)
    return result

