import ctypes

FIELDS = [("flag", "bool"), ("name", "char[6]"), ("value", "double"), ("ids", "uint16_t[3]"), ("tag", "char")]

class CRecord(ctypes.Structure):
    _fields_ = [("flag", ctypes.c_bool), ("name", ctypes.c_char * 6), ("value", ctypes.c_double), ("ids", ctypes.c_uint16 * 3), ("tag", ctypes.c_char)]

class CPacked(ctypes.Structure):
    _pack_ = 1
    _fields_ = [("a", ctypes.c_uint8), ("b", ctypes.c_int32), ("c", ctypes.c_int16)]

VALUES = {"flag": True, "name": b"probe", "value": 2.5, "ids": [1, 2, 65535], "tag": b"Z"}

@test("formats")
def _():
    check_eq(struct_format([("x", "int"), ("y", "double")]), "<i4xd")
    check_eq(struct_format(FIELDS), "<?6s1xd3Hc1x")
    check_eq(struct_format([("a", "uint8_t"), ("b", "int32_t"), ("c", "int16_t")], pack=1), "<Bih")
    check_eq(struct_format([]), "<")

@test("the same bytes as a C structure")
def _():
    data = pack_record(FIELDS, VALUES)
    c = CRecord(True, b"probe", 2.5, (ctypes.c_uint16 * 3)(1, 2, 65535), b"Z")
    check_eq(len(data), ctypes.sizeof(CRecord))
    check_eq(data, bytes(c))
    p = CPacked(7, -2, 300)
    check_eq(pack_record([("a", "uint8_t"), ("b", "int32_t"), ("c", "int16_t")], {"a": 7, "b": -2, "c": 300}, pack=1), bytes(p))

@test("reading bytes back")
def _():
    c = CRecord(False, b"ab", -1.25, (ctypes.c_uint16 * 3)(9, 8, 7), b"q")
    got = unpack_record(FIELDS, bytes(c))
    check_eq(got, {"flag": False, "name": b"ab\x00\x00\x00\x00", "value": -1.25, "ids": [9, 8, 7], "tag": b"q"})
    check_eq(unpack_record(FIELDS, pack_record(FIELDS, VALUES)), {**VALUES, "name": b"probe\x00"})
    check_raises(ValueError, unpack_record, FIELDS, b"\x00" * 10)

